DECLARE
  CURSOR c_pay IS
    SELECT pay_id
    FROM   neft_outward
    WHERE  status = 'PENDING'
    ORDER  BY pay_id
    FOR UPDATE SKIP LOCKED;
  TYPE t_ids IS TABLE OF neft_outward.pay_id%TYPE;
  l_ids t_ids;
BEGIN
  OPEN c_pay;
  FETCH c_pay BULK COLLECT INTO l_ids LIMIT 3;
  CLOSE c_pay;

  FORALL i IN 1 .. l_ids.COUNT
    UPDATE neft_outward
    SET    status = 'SENT', worker_id = 'W2'
    WHERE  pay_id = l_ids(i);

  COMMIT;
END;
/

CREATE OR REPLACE PROCEDURE update_upi_limit (
  p_cust_id      IN cust_limit.cust_id%TYPE,
  p_new_limit    IN cust_limit.daily_upi_limit%TYPE,
  p_read_version IN cust_limit.version_no%TYPE,
  p_user         IN cust_limit.updated_by%TYPE
) AS
BEGIN
  UPDATE cust_limit
  SET    daily_upi_limit = p_new_limit,
         version_no      = version_no + 1,
         updated_by      = p_user
  WHERE  cust_id    = p_cust_id
  AND    version_no = p_read_version;

  IF SQL%ROWCOUNT = 0 THEN
    RAISE_APPLICATION_ERROR(-20001,
      'Record changed by another user. Please refresh and retry.');
  END IF;

  COMMIT;
END update_upi_limit;
/

BEGIN
  update_upi_limit('C101', 75000, 1, 'T2');
  update_upi_limit('C100', 200000, 3, 'T2');
END;
