DECLARE
  TYPE t_id   IS TABLE OF loan_acct.loan_id%TYPE;
  TYPE t_prov IS TABLE OF loan_acct.provision%TYPE;
  l_ids  t_id;
  l_prov t_prov;
BEGIN
  UPDATE loan_acct
  SET    status    = 'NPA',
         provision = ROUND(outstanding * 0.15)
  WHERE  status = 'STD'
  AND    dpd    > 90
  RETURNING loan_id, provision BULK COLLECT INTO l_ids, l_prov;

  FORALL i IN 1 .. l_ids.COUNT
    INSERT INTO npa_audit (loan_id, provision, marked_on)
    VALUES (l_ids(i), l_prov(i), DATE '2026-11-19');

  DBMS_OUTPUT.PUT_LINE(l_ids.COUNT || ' loans marked NPA');
  COMMIT;
END;
/

DECLARE
  TYPE t_alerts IS TABLE OF fraud_alert%ROWTYPE;
  l_alerts t_alerts;
BEGIN
  SELECT * BULK COLLECT INTO l_alerts FROM fraud_alert;
  FOR i IN 1 .. l_alerts.COUNT LOOP
    IF l_alerts(i).risk_score < 80 THEN
      l_alerts.DELETE(i);
    END IF;
  END LOOP;
  FORALL i IN INDICES OF l_alerts
    UPDATE card SET status = 'BLOCKED'
    WHERE card_no = l_alerts(i).card_no;
  DBMS_OUTPUT.PUT_LINE('Blocked: ' || SQL%ROWCOUNT);
  COMMIT;
END;

DECLARE
  e_below_min EXCEPTION;
  PRAGMA EXCEPTION_INIT(e_below_min, -2290);
BEGIN
  FOR r IN (SELECT req_id, acct_no, amount
            FROM rtgs_request ORDER BY req_id) LOOP
    BEGIN
      INSERT INTO rtgs_out (req_id, acct_no, amount)
      VALUES (r.req_id, r.acct_no, r.amount);
    EXCEPTION
      WHEN e_below_min THEN
        INSERT INTO rtgs_reject (req_id, reason)
        VALUES (r.req_id, 'BELOW RTGS MINIMUM');
    END;
  END LOOP;
  COMMIT;
END;
/

DECLARE
  v_old  t_ids;
  v_new  t_ids;
  v_diff t_ids;
BEGIN
  SELECT cust_id BULK COLLECT INTO v_old
  FROM watch_hit WHERE run_date = DATE '2026-11-20';
  SELECT cust_id BULK COLLECT INTO v_new
  FROM watch_hit WHERE run_date = DATE '2026-11-21';
  v_diff := v_new MULTISET EXCEPT DISTINCT v_old;
  FORALL i IN 1 .. v_diff.COUNT
    INSERT INTO new_alert (cust_id, alert_date)
    VALUES (v_diff(i), DATE '2026-11-21');
  COMMIT;
END;
/

